from typing import List, Dict

def summarize_sessions(events: List[Dict[str, str]], active_window: int) -> Dict[str, List[str]]:
    session_history = {}
    for event in events:
        if 'session_id' not in event or 'history' not in event:
            continue
        session_id = event['session_id']
        history = event['history']

        if session_id not in session_history:
            session_history[session_id] = []

        # Ensure the history is ordered and truncated to fit within the active window size
        if len(session_history[session_id]) < active_window:
            session_history[session_id].append(history)
        else:
            session_history[session_id][-1] += history

    return {session_id: sorted(hist, key=lambda x: (len(x), x))[:active_window] for session_id, hist in session_history.items()}
